请对以下 case 进行三维加权评分。

=== case_id ===
Case-04-focus-067

=== 用户原始指令 (query.txt) ===
做个背景上加文字的卡片，专注时间倒计时，点开始，显示已连接状态

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "做个背景上加文字的卡片，专注时间倒计时，点开始，显示已连接状态",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "intelligent_scene_entry"
      }
    }
  ],
  "dataModel": {
    "value": {
      "focus": {
        "title": "专注倒计时",
        "countdownText": "25:00",
        "connectionStatus": "已连接",
        "modeText": "专注模式",
        "actionText": "开始",
        "asset": {
          "focusIcon": "resources/base/media/icon_focus.png"
        },
        "running": false
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "focus_icon",
      "src": "resources/base/media/icon_focus.png",
      "use": "focus icon",
      "description": "专注模式语义图标，适合用于专注倒计时或手机专注状态的视觉锚点。",
      "bindTo": "/focus/asset/focusIcon",
      "static": true
    }
  ]
}

